string_json_schema!(PackageId);

impl PackageId {
    /// Parses package identity string.
    ///
    /// # Errors
    ///
    /// Returns `Err` if `s` is empty, starts with `/`, contains `..`, or has a known ecosystem prefix followed by an empty name.
    pub fn parse(s: &str) -> Result<Self, PackageIdParseError> {
        if s.is_empty() {
            return Err(PackageIdParseError::Empty);
        }
        if s.starts_with('/') {
            return Err(PackageIdParseError::LeadingSlash { raw: s.to_string() });
        }
        if s.starts_with('-') {
            return Err(PackageIdParseError::LeadingHyphen { raw: s.to_string() });
        }
        if s.contains("..") {
            return Err(PackageIdParseError::PathTraversal { raw: s.to_string() });
        }

        if let Some((prefix, remainder)) = s.split_once(':')
            && let Some(ecosystem) = Ecosystem::from_prefix(prefix)
        {
            Self::validate_prefixed_remainder(s, prefix, remainder)?;
            return Ok(PackageId::Prefixed {
                ecosystem,
                name: remainder.to_string(),
            });
        }

        if let Some((prefix, remainder)) = s.split_once('/')
            && let Some(ecosystem) = Ecosystem::from_prefix(prefix)
        {
            Self::validate_prefixed_remainder(s, prefix, remainder)?;
            return Ok(PackageId::Prefixed {
                ecosystem,
                name: remainder.to_string(),
            });
        }

        Ok(PackageId::Bare(s.to_string()))
    }

    /// Shared validation for the remainder of an ecosystem-prefixed id (the part
    /// after the `:` or `/` separator), used by both prefixed forms in [`Self::parse`].
    fn validate_prefixed_remainder(raw: &str, prefix: &str, remainder: &str) -> Result<(), PackageIdParseError> {
        if remainder.is_empty() {
            return Err(PackageIdParseError::EmptyNameAfterPrefix {
                raw: raw.to_string(),
                prefix: prefix.to_string(),
            });
        }
        if remainder.starts_with('-') {
            return Err(PackageIdParseError::LeadingHyphen { raw: raw.to_string() });
        }
        if remainder.contains("..") {
            return Err(PackageIdParseError::PathTraversal { raw: raw.to_string() });
        }
        Ok(())
    }

    /// The slash form of a colon-qualified reference (`cargo:foo` becomes `cargo/foo`), or `None` when `s` is not one.
    pub fn colon_form_canonical(s: &str) -> Option<String> {
        let (prefix, remainder) = s.split_once(':')?;
        (Ecosystem::from_prefix(prefix).is_some() && !remainder.is_empty()).then(|| format!("{prefix}/{remainder}"))
    }

    /// Returns the canonical display form: bare names as-is, prefixed ids as `ecosystem/name`.
    pub fn display_name(&self) -> String {
        match self {
            PackageId::Bare(name) => name.clone(),
            PackageId::Prefixed { ecosystem, name } => {
                format!("{}/{}", ecosystem.prefix(), name)
            }
        }
    }

    /// Returns the ecosystem this id is scoped to, or `None` for a [`PackageId::Bare`] id.
    pub fn ecosystem(&self) -> Option<Ecosystem> {
        match self {
            PackageId::Bare(_) => None,
            PackageId::Prefixed { ecosystem, .. } => Some(*ecosystem),
        }
    }

    /// Returns the package name without any ecosystem prefix.
    pub fn name(&self) -> &str {
        match self {
            PackageId::Bare(name) => name,
            PackageId::Prefixed { name, .. } => name,
        }
    }

    /// Weak "could be the same package" check, not strict equality.
    ///
    /// `Bare(x)` matches any `Prefixed(_, x)` (bare is an ecosystem wildcard);
    /// `Prefixed(e1, x)` matches `Prefixed(e2, x)` only if `e1 == e2`; exact
    /// equality always matches.
    ///
    /// **Caller contract**: a bare lookup can match packages in two or more ecosystems, so a caller must
    /// collect all matches and error on 2+, never take the first silently. Resolving a changeset or config
    /// selector goes through the workspace identity index instead, which also knows each manifest's own name.
    pub fn matches(&self, other: &Self) -> bool {
        if self == other {
            return true;
        }
        if self.name() == other.name() {
            match (self.ecosystem(), other.ecosystem()) {
                (None, _) | (_, None) => true,
                (Some(e1), Some(e2)) => e1 == e2,
            }
        } else {
            false
        }

    #[error("workspace is not in pre-release mode")]
    #[diagnostic(code(E244), help("callisto pre enter <tag>"))]
    PreNotActive,

    #[error("release pull requests do not support pre-release mode (tag `{tag}`)")]
    #[diagnostic(
        code(E318),
        help("release prereleases locally with `callisto version` and `callisto release`, or run `callisto pre exit` first")
    )]
    ReleasePrInPreMode { tag: String },

    #[error("invalid package spec `{spec}`; expected `package-name:severity`")]
    #[diagnostic(code(E270), help("pass a colon-separated pair, for example `cargo/foo:patch`"))]
    AddInvalidPackageSpec { spec: String },

    #[error("Invalid severity `{value}`. Must be none, patch, minor, or major.")]
    #[diagnostic(code(E271), help("pass one of: none, patch, minor, major"))]
    InvalidSeverity { value: String },

    #[error("no packages found in workspace")]
    #[diagnostic(
        code(E272),
        help("check that callisto.toml and package manifests are discoverable from the current directory")
    )]
    AddNoPackagesInWorkspace,
    ReleaseReceipt,
}

/// Arguments for the hidden `help` subcommand: prints a subcommand's help
/// text even though `disable_help_subcommand` turns off clap's own
/// automatic one, so the visible `--help` listing stays at eight commands.
#[derive(Args, Clone, Debug, Default)]
pub struct HelpArgs {
    /// Subcommand (and nested subcommand) to print help for, e.g. `release plan`; omit for the root help.
    pub command: Vec<String>,
}

/// Arguments for the `add` command.
#[derive(Args, Clone, Debug)]
pub struct AddArgs {
    /// Package and severity to include, as `name:severity` (none, patch, minor, or major); repeatable. Omit to enter the interactive wizard.
    #[arg(long = "package", value_name = "NAME:SEVERITY")]
    pub packages: Vec<String>,
    /// Human-readable summary of the change to record in the changeset.
    #[arg(long)]
    pub summary: Option<String>,
}

