            context.runner(),
            programs::NPM,
            &args,
            &context.root().join(workspace_dir),
            timeouts::REGISTRY_QUERY,
            true,
        )
        .ok()?
        .ok()?;
        output.success().then(|| npm_view_repository(&output.stdout)).flatten()
    }

